content.text:
        return lvl == "I" or lvl == "H" or lvl == "A"
    if typ == "STREAM" or typ == "RESET_STREAM" or typ == "STOP_SENDING":
        return lvl == "Z" or lvl == "A"
    if typ == "CLOSE":
        if fr["app"]:
            return lvl == "Z" or lvl == "A"
        return True
    if typ == "HANDSHAKE_DONE":
        return False
    return False


def main():
    try:
        raw = sys.stdin.buffer.read(MAX_REQUEST + 1)
        obj = _parse(raw)
        _validate_root(obj)
        results = []
        for tr in obj["traces"]:
            runner = TraceRunner(tr)
            res = runner.run(tr["events"])
            res["id"] = tr["id"]
            results.append(res)
        out = {"version": 1, "results": results}
    except InvalidInput:
        out = {"error": "INVALID_INPUT"}
    except Exception:
        # Any malformed input that slipped past explicit checks must not
        # crash the auditor.  (Valid inputs should never reach this path.)
        out = {"error": "INVALID_INPUT"}
    try:
        sys.stdout.write(json.dumps(out, separators=(",", ":")))
        sys.stdout.write("\n")
    except Exception:
        # Last-resort interface safety; nothing useful can be emitted here.
        pass


if __name__ == "__main__":
    main()
